import 'server-only';
import { z } from 'zod';

const PG_URL = /^postgres(ql)?:\/\//;

function isValidTimeZone(tz: string): boolean {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}

const schema = z.object({
  AUTH0_DOMAIN: z.string().min(1),
  AUTH0_CLIENT_ID: z.string().min(1),
  AUTH0_CLIENT_SECRET: z.string().min(1),
  AUTH0_SECRET: z.string().min(32, 'must be at least 32 characters (openssl rand -hex 32)'),
  APP_BASE_URL: z.string().url().optional(),

  DATABASE_URL: z.string().regex(PG_URL, 'must be a postgres:// connection string'),
  DB_POOL_MAX: z.coerce.number().int().positive().default(5),
  DATABASE_URL_TEST: z.string().regex(PG_URL, 'must be a postgres:// connection string').optional(),

  GOOGLE_CLOUD_PROJECT: z.string().min(1),
  GOOGLE_CLOUD_LOCATION: z.string().min(1).catch('us-central1'), // blank line in .env also falls back
  GEMINI_MODEL: z.string().default('gemini-3.8-flash'),
  GEMINI_SEARCH_MODEL: z.string().default('gemini-3.8-flash'),

  DATAANDAPIS_KEY: z.string().min(1),
  OFF_BASE_URL: z.string().url().default('https://world.openfoodfacts.org'),
  OFF_USER_AGENT: z.string().min(1),
  RECIPE_FETCH_USER_AGENT: z.string().min(1),

  ELEVENLABS_API_KEY: z.string().optional(),
  ELEVENLABS_VOICE_ID: z.string().default('JBFqnCBsd6RMkjVDRZzb'),
  ELEVENLABS_MODEL_ID: z.string().default('eleven_flash_v2_5'),

  DEFAULT_TZ: z.string().refine(isValidTimeZone, 'must be an IANA time zone').default('America/Vancouver'),
});

type Env = z.infer<typeof schema>;

let cached: Env | null = null;

/**
 * Validates server env vars with Zod and fails fast. Skipped during `vitest`
 * (NODE_ENV=test) so pure unit tests don't need every production secret —
 * anything that actually calls an external API should mock its own env reads.
 */
export function getEnv(): Env {
  if (cached) return cached;
  // `KEY=` (empty, as in .env.example) means unset, not an invalid empty string.
  const source = Object.fromEntries(Object.entries(process.env).filter(([, v]) => v !== undefined && v.trim() !== ''));
  // `next build` imports route modules without runtime secrets; validate at request time instead.
  if (process.env.NODE_ENV === 'test' || process.env.NEXT_PHASE === 'phase-production-build') {
    cached = schema.partial().parse(source) as Env;
    return cached;
  }
  const parsed = schema.safeParse(source);
  if (!parsed.success && process.env.NODE_ENV !== 'production') {
    // Local dev without every key: warn and run; features needing a missing key fail on use.
    console.warn('[env] missing env vars (dev only, not fatal):', Object.keys(parsed.error.flatten().fieldErrors).join(', '));
    cached = schema.partial().parse(source) as Env;
    return cached;
  }
  if (!parsed.success) {
    console.error('[env] invalid/missing environment variables:', parsed.error.flatten().fieldErrors);
    throw new Error('Invalid environment configuration — see logs above.');
  }
  if (process.env.NODE_ENV === 'production' && !parsed.data.APP_BASE_URL) {
    console.error('[env] invalid/missing environment variables: { APP_BASE_URL: [ "is required in production" ] }');
    throw new Error('Invalid environment configuration — see logs above.');
  }
  cached = parsed.data;
  return cached;
}

import 'server-only';
import { GoogleGenAI, type Part } from '@google/genai';
import type { ZodType } from 'zod';
import { getEnv } from '../env';

let client: GoogleGenAI | null = null;

function getClient(): GoogleGenAI {
  // Vertex AI via Application Default Credentials (`gcloud auth application-default login` locally).
  if (!client) {
    const env = getEnv();
    client = new GoogleGenAI({ vertexai: true, project: env.GOOGLE_CLOUD_PROJECT, location: env.GOOGLE_CLOUD_LOCATION });
  }
  return client;
}

export interface GeminiImage {
  mimeType: 'image/jpeg' | 'image/png' | 'image/webp' | 'image/heic' | 'image/heif';
  base64: string;
}

async function callWithTimeout<T>(fn: (signal: AbortSignal) => Promise<T>, timeoutMs: number): Promise<T> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fn(controller.signal);
  } finally {
    clearTimeout(timer);
  }
}

function stripJsonFences(text: string): string {
  return text
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/, '')
    .trim();
}

function tryParseJson(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
}

/**
 * JSON-mode call, NO tools (§10.3.1). Validates with zod; strips ```json
 * fences; 1 retry if the response doesn't parse or doesn't match `zod` —
 * structured output guarantees schema-shaped JSON, not correct values
 * (https://ai.google.dev/gemini-api/docs/structured-output), so callers must
 * still sanity-check the data.
 */
export async function geminiJson<T>(opts: {
  system?: string;
  text: string; // put the text prompt BEFORE images (docs tip)
  images?: GeminiImage[];
  jsonSchema: object; // Gemini JSON-Schema subset (§10.3.6)
  zod: ZodType<T>;
  model?: string;
  timeoutMs?: number;
}): Promise<{ data: T; model: string }> {
  const env = getEnv();
  const model = opts.model ?? env.GEMINI_MODEL;
  const timeoutMs = opts.timeoutMs ?? 30_000;

  const parts: Part[] = [{ text: opts.text }];
  for (const image of opts.images ?? []) {
    parts.push({ inlineData: { mimeType: image.mimeType, data: image.base64 } });
  }

  const attempt = async () => {
    const response = await callWithTimeout(
      (signal) =>
        getClient().models.generateContent({
          model,
          contents: [{ role: 'user', parts }],
          config: {
            systemInstruction: opts.system,
            responseMimeType: 'application/json',
            responseSchema: opts.jsonSchema,
            abortSignal: signal,
          },
        }),
      timeoutMs,
    );
    const parsed = tryParseJson(stripJsonFences(response.text ?? ''));
    return opts.zod.safeParse(parsed);
  };

  const first = await attempt();
  if (first.success) return { data: first.data, model };

  const second = await attempt();
  if (second.success) return { data: second.data, model };

  throw new Error(`geminiJson: response did not match schema after 1 retry: ${second.error.message}`);
}

/**
 * Grounded search call, NO response schema (avoids the 2025–26
 * grounding+JSON bugs documented in §9 F6). Reads `groundingMetadata` off
 * the first candidate (§17 item 1, confirmed against @google/genai 3.0.0).
 */
export async function geminiGroundedSearch(opts: {
  prompt: string;
  model?: string;
  timeoutMs?: number;
}): Promise<{
  text: string;
  sources: Array<{ uri: string; title: string | null }>;
  webSearchQueries: string[];
  searchEntryPointHtml: string | null;
}> {
  const env = getEnv();
  const model = opts.model ?? env.GEMINI_SEARCH_MODEL;
  const timeoutMs = opts.timeoutMs ?? 45_000;

  const response = await callWithTimeout(
    (signal) =>
      getClient().models.generateContent({
        model,
        contents: [{ role: 'user', parts: [{ text: opts.prompt }] }],
        config: { tools: [{ googleSearch: {} }], abortSignal: signal },
      }),
    timeoutMs,
  );

  const grounding = response.candidates?.[0]?.groundingMetadata;
  const sources = (grounding?.groundingChunks ?? [])
    .map((chunk) => chunk.web)
    .filter((web): web is { uri: string; title?: string } => Boolean(web?.uri))
    .map((web) => ({ uri: web.uri as string, title: web.title ?? null }));

  return {
    text: response.text ?? '',
    sources,
    webSearchQueries: grounding?.webSearchQueries ?? [],
    searchEntryPointHtml: grounding?.searchEntryPoint?.renderedContent ?? null,
  };
}

#!/usr/bin/env node
// Gemini smoke test (§18.2 task 0.7, §17 item 1): one grounded-search call and
// one vision JSON call. Uses Vertex AI with Application Default Credentials.
// Usage: gcloud auth application-default login && GOOGLE_CLOUD_PROJECT=... node scripts/gemini-smoke.mjs
import { GoogleGenAI } from '@google/genai';

const project = process.env.GOOGLE_CLOUD_PROJECT;
if (!project) {
  console.error('GOOGLE_CLOUD_PROJECT is required');
  process.exit(1);
}
const location = process.env.GOOGLE_CLOUD_LOCATION ?? 'us-central1';
const model = process.env.GEMINI_MODEL ?? 'gemini-3.8-flash';
const searchModel = process.env.GEMINI_SEARCH_MODEL ?? 'gemini-3.8-flash';
const ai = new GoogleGenAI({ vertexai: true, project, location });

console.log(`[smoke] models: json=${model} search=${searchModel}`);

// 1. Grounded search (no response schema).
const grounded = await ai.models.generateContent({
  model: searchModel,
  contents: [{ role: 'user', parts: [{ text: 'Find 2 real spinach pasta recipe pages. Reply one line per recipe: <title> | <url>.' }] }],
  config: { tools: [{ googleSearch: {} }] },
});
const grounding = grounded.candidates?.[0]?.groundingMetadata;
console.log(`[smoke] grounded text: ${(grounded.text ?? '').slice(0, 200)}`);
console.log(`[smoke] grounding chunks: ${grounding?.groundingChunks?.length ?? 0}`);
console.log(`[smoke] web queries: ${(grounding?.webSearchQueries ?? []).join(' | ') || '(none)'}`);
if (!grounding || (grounding.groundingChunks?.length ?? 0) === 0) {
  console.error('[smoke] FAIL: no grounding metadata — check model grounding support (§17 item 3)');
  process.exit(1);
}

// 2. Vision JSON call (1x1 red png — tests schema output, not recognition).
const redDot = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==';
const json = await ai.models.generateContent({
  model,
  contents: [
    {
      role: 'user',
      parts: [
        { text: 'Describe this image in JSON.' },
        { inlineData: { mimeType: 'image/png', data: redDot } },
      ],
    },
  ],
  config: {
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'object',
      required: ['color'],
      properties: { color: { type: 'string' } },
    },
  },
});
console.log(`[smoke] vision json: ${(json.text ?? '').slice(0, 200)}`);
JSON.parse(json.text ?? '');
console.log('[smoke] PASS: grounded search + vision JSON both work');
